const e=[{id:1,icon:"Flame",emoji:"🔥",accent:"#dc2626",title:"مەترسییێن ئاگری",subtitle:"ئاگەهدار ببە و خوە بپارێزە",summary:"ئاگر گەلەک ب مفایە بۆ چێکرنا خوارنێ و گەرمکرنا مالێ، بەلێ ئەگەر ئەم وریا نەبین، دشێت زیانێن مەزن بگەهینیتە مە. فێربوونا ڕێسایێن ئاگری نیشانا زیرەکییا تە یە!",blocks:[{heading:"شخاتە و چەرخ بۆ یارییێ نینن",body:"شخاتە و چەرخ تەنێ بۆ مەزنانە. یاریکرن ب وان دشێت ئێکسەر ئاگرەک هەلکەت و تە بسۆژیت.",image:"media/images/fire_danger_1.png"},{heading:"ژ سۆبەیێ دویر بکەڤە",body:"ژ سۆبەیێ و هەر ئامێرەکێ گەرمکرنێ لایێ کێم سێ هەنگاڤان دویر بمینە، دا کو جلکێن تە ئاگر نەگرن.",image:"media/images/fire_danger_2.png"},{heading:"ڕاوەستە، بکەڤە عەردی، خوە بزڤڕینە",body:"ئەگەر ئاگر ب جلکێن تە کەت: نەڕەڤە! ڕاوەستە، بکەڤە سەر عەردی، سەر و چاڤێن خوە ب دەستان بگرە و خوە ل سەر عەردی بزڤڕینە تا ئاگر ڤەدمریت. پاشان ب دەنگێ بلند گازی مەزنەکی بکە.",image:"media/images/fire_danger_3.png"}],examples:["دەمێ تو ئاگرەک دبینی، ب دەنگێ بلند هاوار بکە: ئاگر! ئاگر! و ژ وی جهی دویر بکەڤە.","چو جاران یارییێ ب چەرخێ نەکە، تەنانەت ئەگەر ڤەمراندی ژی بیت.","ئەگەر دوکێل ل ژوورێ هەبیت، خوە نزم بکە و ل سەر دەست و چۆکان بەرەڤ دەرڤە بخشە."],video:"media/videos/lesson02_fire.mp4",game:{instruction:"کیشک ژ ڤان تشتان د مەترسیدارن؟",items:[{text:"شخاتە",emoji:"🔥",correct:!0},{text:"بویکۆک",emoji:"🧸",correct:!1},{text:"سۆبەیا غازێ",emoji:"♨️",correct:!0},{text:"پەرتووک",emoji:"📚",correct:!1}]},activity:{prompt:"تو دچیە مەتبەخێ و دبینی پارچە قوماشەک کەفتیە سەر تەباخێ و دسۆژیت، دێ چ کەی؟",image:"media/images/activity_fire.png",options:[{text:"دێ ژ مەتبەخێ دەرکەڤم و ب دەنگێ بلند بێژمە دایکێ یان بابێ",correct:!0},{text:"دێ هەول دەم ب دەستێن خوە ڤەمرینم",correct:!1},{text:"دێ ل وێرێ ڕاوەستم و تەماشە کەم",correct:!1},{text:"دێ خوە ڤەشێرم",correct:!1}]}},{id:2,icon:"Zap",emoji:"⚡",accent:"#ca8a04",title:"مەترسییێن کارەبایێ",subtitle:"کارەبا یاری نینە، وریا ببە",summary:"کارەبا هێزەکا نەدیارە کو گلۆپ و تەلەڤیزیۆنێن مە پێ کار دکەن. ئەڤ هێزە گەلەک ب مفایە، بەلێ ئەگەر ئەم ب شێوەیەکێ خەلەت دەست بدەینێ، دشێت زیانەکا مەزن بگەهینیتە دل و جەستەیێ مە.",blocks:[{heading:"دەست نەدە پلاکێن کارەبایێ",body:"پلاکێن کارەبایێ تەنێ بۆ وایەرێن ئامێرێن مالێ نە. چو جاران مۆرک، قەلەم یان تشتێن ئاسنی نەکە د پلاکێ دا، چونکی کارەبا دێ تە گریت.",image:"media/images/electricity_1.png"},{heading:"ئاڤ و کارەبا دژمنێن ئێکن",body:"ئاڤ کارەبایێ ب لەز دگوهێزیت. چو جاران ب دەستێن تەڕ، یان دەمێ تو د حەمامێ دا یی، دەست نەدە سویچ و وایەرێن کارەبایێ.",image:"media/images/electricity_2.png"},{heading:"وایەرێن بڕی و ستوونێن کارەبایێ",body:"ئەگەر تە وایەرەکێ بڕی ل سەر جاددەیێ یان ل مالێ دیت، نێزیکی وی نەبە و ئێکسەر بێژە مەزنەکی. هەروەسا ل دەمێ بارانێ دەست نەدە ستوونێن کارەبایێ یێن سەر جاددەیان.",image:"media/images/electricity_3.png"}],examples:["چو جاران وایەرێ شەحنا مۆبایلێ نەکە دەڤێ خوە.","وایەرێن مۆبایل و ئایپادێ ژ پلاکێ نەکێشە، بێژە مەزنەکی دا کو ئەو دەربێخیت.","ئەگەر تە دیت وایەرەک پریسکان دهاڤێژیت یان بێهنەکا خراب ژێ دهێت، ئێکسەر بێژە دایکێ یان بابێ."],video:"media/videos/lesson02_electricity.mp4",game:{instruction:"کیشک ژ ڤان کاران د سەلامەتن؟",items:[{text:"یاریکرن ب ترمبێلا پلاستیکی",emoji:"🚗",correct:!0},{text:"دەستدان ل وایەرەکێ بڕی",emoji:"⚡",correct:!1},{text:"نڤیسین ب قەلەمێ دار",emoji:"✏️",correct:!0},{text:"کرنا مێخەکێ ئاسنی د پلاکێ دا",emoji:"🔌",correct:!1}]},activity:{prompt:"تە دیت برایێ تە یێ بچووک ل سەر عەردی یە و دڤێت وایەرێ شەحنا مۆبایلێ بکەتە دەڤێ خوە، دێ چ کەی؟",image:"media/images/activity_electricity.png",options:[{text:"دێ ئێکسەر ب دەنگێ بلند گازی مەزنان کەم دا کو وایەری ژێ دویر بکەن",correct:!0},{text:"دێ ل هیڤییێ بمینم تا ئەو دەردئێخیت",correct:!1},{text:"ئەز ژی دێ دگەل وی یارییێ پێ کەم",correct:!1},{text:"دێ خوە ڤەشێرم",correct:!1}]}},{id:3,icon:"TrafficCone",emoji:"🚦",accent:"#2563eb",title:"جاددە و ترمبێل",subtitle:"سەلامەتییا تە ل سەر جاددەیێ",summary:"جاددە جهێ هاتن و چوونا ترمبێلێن مەزن و ب لەزە. دا کو ئەم پاراستی بین، دڤێت ئەم ڕێسایێن هاتنوچوونێ باش فێر ببین و چو جاران ب تنێ نەچینە سەر جاددەیێ.",blocks:[{heading:"دەستێ مەزنان بگرە",body:"دەمێ تو دچیە دەرڤە، هەمیشە دەستێ دایکێ، بابێ یان کەسەکێ مەزن بگرە، دا کو تو پاراستی بی و ترمبێل تە ببینن.",image:"media/images/traffic_1.png"},{heading:"پشکنینا جاددەیێ (چەپ و ڕاست)",body:"بەری تو دگەل مەزنەکی جاددەیێ ببڕی، ڕاوەستە! تەماشەی لایێ چەپێ بکە، پاشان لایێ ڕاستێ، پاشان جارەکا دی لایێ چەپێ. ئەگەر چو ترمبێل نەدهاتن، ڕاستەوخۆ دەرباز ببە؛ نەڕەڤە و د ناڤ جاددەیێ دا ڕانەوەستە.",image:"media/images/traffic_2.png"},{heading:"زمانێ چرایێن ترافیکێ",body:"ل جهێ دەرباسبوونا پیادەیان، تەماشەی وی چرایی بکە یێ وێنەیێ مرۆڤەکێ بچووک تێدا. مرۆڤێ سۆر: ئەم دوەستین. مرۆڤێ کەسک: ئەم تەماشەی چەپێ، ڕاستێ و جارەکا دی چەپێ دکەین، پاشان دەستێ مەزنەکی دگرین و دەرباز دبین. هەمیشە ژ سەر هێلێن پیادەیان (زیبرا) دەرباز ببە.",image:"media/images/traffic_3.png"}],examples:["چو جاران ل سەر جاددەیێ یارییێ ب تەپکێ یان سکۆتەرێ نەکە.","د ناڤ ترمبێلێ دا، هەمیشە قاییشا سەلامەتییێ ببەستە.","ل پشت ترمبێلێن ڕاوەستیای یارییێ نەکە، چونکی دەمێ شۆفێر ترمبێلێ ب پاشڤە دبەت، تە نابینیت."],video:"media/videos/lesson03_traffic.mp4",game:{instruction:"ل سەر چرایێ پیادەیان، کیش مرۆڤ دبێژیتە تە: ڕاوەستە؟",items:[{text:"مرۆڤێ کەسک (دگەل مەزنەکی دەرباز ببە)",emoji:"🟢",correct:!1},{text:"مرۆڤێ سۆر (ڕاوەستە)",emoji:"🔴",correct:!0}]},activity:{prompt:"تەپکا تە ڕەڤی و چوو ناڤەڕاستا جاددەیێ و ترمبێل د گەلەکن، دێ چ کەی؟",image:"media/images/activity_traffic.png",options:[{text:"ناچمە دویڤ دا و ئێکسەر گازی کەسەکێ مەزن دکەم دا کو هاریکارییا من بکەت",correct:!0},{text:"ب لەز دڕەڤمە دویڤ تەپکێ دا",correct:!1},{text:"ل هیڤییێ دمینم تا ترمبێلەک تەپکێ بپەقینیت",correct:!1},{text:"دگریم و هاوار دکەم",correct:!1}]}},{id:4,icon:"Home",emoji:"🏠",accent:"#16a34a",title:"عەردەهەژین",subtitle:"چەوانییا خوەپاراستنێ",summary:"هندەک جاران عەرد دهەژیت. ئەڤە دیاردەیەکا سروشتییە و دبێژنێ عەردەهەژین. پێدڤییە ئەم ئارام بین و بزانین چەوا خوە بپارێزین.",blocks:[{heading:"بکەڤە سەر چۆکان، خوە بپارێزە، بگرە (Drop, Cover, Hold On)",body:"ئەگەر عەرد هەژیا، ئێکسەر بکەڤە سەر چۆکان، بچە بن مێزەکا قایم، سەرێ خوە بپارێزە و لنگێ مێزێ باش بگرە تا هەژین ڕادوەستیت.",image:"media/images/earthquake_1.png"},{heading:"ژ شووشە و پەنجەرەیان دویر بکەڤە",body:"ل دەمێ عەردەهەژینێ، شووشەیێن پەنجەرەیان و ئایینە دشێن بشکێن و تە بریندار بکەن، ژبەر هندێ ژ وان دویر بکەڤە.",image:"media/images/earthquake_2.png"},{heading:"نەڕەڤە دەرڤە و ئەسانسۆرێ بکار نەئینە",body:"ل دەمێ هەژینێ، ڕەڤین بۆ دەرڤە مەترسیدارە، چونکی دبیت تشت ژ ئاڤاهی بکەڤنە سەر تە. هەروەسا چو جاران ئەسانسۆرێ بکار نەئینە.",image:"media/images/earthquake_3.png"}],examples:["ئەگەر مێز نەبوو، ل بن دیوارەکێ دویر ژ پەنجەرەیان بکەڤە سەر چۆکان و ب دەستان سەر و ستۆیێ خوە بپارێزە.","ئارام ببە و قێری نەکە، چونکی ترس کارێ تە گران دکەت.","پشتی هەژین ڕادوەستیت، هێدی هێدی و دگەل مەزنان ژ ئاڤاهی دەرکەڤە."],video:"media/videos/lesson04_earthquake.mp4",game:{instruction:"ل دەمێ عەردەهەژینێ، کیش جهـ ژ ڤان سەلامەتە بۆ خوەپاراستنێ؟",items:[{text:"ل بن مێزەکا قایم",emoji:"🪑",correct:!0},{text:"نێزیکی پەنجەرەیێن شووشە",emoji:"🪟",correct:!1},{text:"ناڤ ئەسانسۆرێ",emoji:"🛗",correct:!1},{text:"ل سەر بانێ خانی",emoji:"🏠",correct:!1}]},activity:{prompt:"تو د ژوورێ دا یی و خانی دەست ب هەژینێ کر، دێ چ کەی؟",image:"media/images/activity_earthquake.png",options:[{text:"دچمە بن مێزێ، سەرێ خوە دپارێزم و لنگێ مێزێ دگرم",correct:!0},{text:"ب ڕەڤین بەرەڤ دەرگەهێ دەرڤە دچم",correct:!1},{text:"دگریم و ب تنێ دڕاوەستم",correct:!1},{text:"دچمە بەر پەنجەرەیێ و تەماشەی دەرڤە دکەم",correct:!1}]}},{id:5,icon:"Scissors",emoji:"✂️",accent:"#9333ea",title:"تشتێن تیژ و بریندارکەر",subtitle:"جەستەیێ خوە بپارێزە",summary:"کێر، مەقەس و هەمی تشتێن تیژ دشێن ب ساناهی پێستا مە ببڕن و خوین ژێ بهێت. ئەڤ تشتە بۆ یارییێ نینن و تەنێ ب وریایی دهێنە بکارئینان.",blocks:[{heading:"کێر تەنێ بۆ مەزنانە",body:"کێرێن مەتبەخێ گەلەک تیژن و تەنێ مەزن بکار دئینن. چو جاران هەول نەدە ب تنێ تشتەکی ب کێرێ ببڕی.",image:"media/images/sharp_1.png"},{heading:"مەقەسێن سەلامەت یێن زارۆکان",body:"ئەگەر تو مەقەسێ بۆ کارێن قوتابخانێ بکار بینی، دڤێت سەرێ وێ خڕ بیت و یا تایبەت ب زارۆکان بیت، دا کو تو بریندار نەبی.",image:"media/images/sharp_2.png"},{heading:"شووشە و پارچەیێن شکەستی",body:"ئەگەر پەرداخەک یان ئایینەیەک شکا، ب چو شێوەیان دەست نەدێ و پێ ل سەر نەدە. ئێکسەر ژ وی جهی دویر بکەڤە و بێژە مەزنەکی، چونکی پارچەیێن بچووک یێن شووشەیێ گەلەک مەترسیدارن.",image:"media/images/sharp_3.png"}],examples:["چو جاران ب تشتەکێ تیژ ڤە غار نەدە.","دەرزی و پینزێن دایکێ بۆ یارییێ نینن، دەست نەدە وان.","ئەگەر تو بریندار بووی، ئێکسەر بێژە مەزنان دا کو چارەسەرییا تە بکەن."],video:"media/videos/lesson05_sharp.mp4",game:{instruction:"کیشک ژ ڤان تشتان د مەترسیدارن و دڤێت ئەم دەست نەدەینێ؟",items:[{text:"کێر",emoji:"🔪",correct:!0},{text:"تەپک",emoji:"⚽",correct:!1},{text:"قەلەمێن ڕەنگاوڕەنگ",emoji:"✏️",correct:!1},{text:"بویکۆک",emoji:"🧸",correct:!1}]},activity:{prompt:"تو دبینی پەرداخەکا ئاڤێ ل سەر عەردی شکەستییە و کەس ل وێرێ نینە، دێ چ کەی؟",image:"media/images/activity_sharp.png",options:[{text:"ژ وی جهی دویر دکەڤم و دچمە دەف دایکێ یان بابێ و دبێژمێ دا کو پاقژ بکەن",correct:!0},{text:"ب دەستێن خوە پارچەیێن شووشەیێ کۆم دکەم",correct:!1},{text:"پێ ل سەر ددانم دا بزانم کا تیژە یان نە",correct:!1},{text:"دکەمە بن مافووری دا کو کەس نەبینیت",correct:!1}]}},{id:6,icon:"CookingPot",emoji:"🍳",accent:"#ea580c",title:"مەتبەخێ سەلامەت",subtitle:"جهێ خوارنێ یە، نە جهێ یارییێ",summary:"مەتبەخ ئەو جهێ مالێ یە کو خوارنێن خۆش تێدا دهێنە چێکرن، بەلێ پڕە ژ گەرمی، ئاگر و ئاڤا کەلی کو دشێن زیانێ بگەهیننە مە.",blocks:[{heading:"تەباخ و فڕن د گەرمن",body:"دەمێ تەباخ هەلکری بیت، نێزیکی وێ نەبە. گەرمییا وێ دشێت تە بسۆژیت، تەنانەت ئەگەر تو دەست نەدەیێ ژی.",image:"media/images/kitchen_1.png"},{heading:"مەنجەلێن سەر تەباخێ",body:"چو جاران دەست نەدە دەسکێن مەنجەلان و وان نەکێشە. مەزن دەسکان بەرەڤ ناڤا تەباخێ دزڤڕینن، دا کو مەنجەل نەکەڤن و ئاڤا کەلی نەڕژیتە سەر تە.",image:"media/images/kitchen_2.png"},{heading:"مەتبەخ جهێ یارییێ نینە",body:"یاری ل ناڤ مەتبەخێ مەترسیدارە، چونکی دبیت تو بکەڤیە سەر تەباخێ یان کێرەکێ. باشترین جهـ بۆ یارییێ ژوورا تە یان هۆلا مالێ یە.",image:"media/images/kitchen_3.png"}],examples:["چو جاران دەست نەدە فڕنا گەرم دەمێ نان تێدا دهێتە چێکرن.","ئاگەهداری ئاڤا کەلی و چایا گەرم ببە، دشێن تە بسۆژن!","ل ناڤ مەتبەخێ غار نەدە، چونکی عەردێ وێ گەلەک جاران خلیسۆکە."],video:"media/videos/lesson06_kitchen.mp4",game:{instruction:"کیش جهـ ژ ڤان دروستە بۆ یاریکرنێ ب تەپکێ؟",items:[{text:"هۆلا مالێ",emoji:"🛋️",correct:!0},{text:"سەر تەباخێ",emoji:"🍳",correct:!1},{text:"باخچێ مالێ",emoji:"🌳",correct:!0},{text:"ناڤ مەنجەلا خوارنێ",emoji:"🍲",correct:!1}]},activity:{prompt:"دایکا تە ل مەتبەخێ خوارنێ چێ دکەت و تەباخ هەلکرییە، دێ ل کیڤە یارییێ کەی؟",image:"media/images/activity_kitchen.png",options:[{text:"دچمە ژوورا خوە یان ل هۆلێ ب هێدی یارییێ دکەم",correct:!0},{text:"دچمە نێزیکی تەباخێ و یارییێ دکەم",correct:!1},{text:"دەست ددەمە مەنجەلان دا بزانم کا چ تێدایە",correct:!1},{text:"ل ناڤ مەتبەخێ تەپکێ دهاڤێژم",correct:!1}]}},{id:7,icon:"PlugZap",emoji:"💧",accent:"#0891b2",title:"ئاڤ و کارەبا: دوو دژمنێن مەزن",subtitle:"خوە ژ شۆکا کارەبایێ بپارێزە",summary:"ئاڤ و کارەبا چو جاران نابیت بگەهنە ئێک. ئاڤ کارەبایێ ب لەز دگوهێزیت، و ئەگەر جەستەیێ تە تەڕ بیت، کارەبا دێ تە ب هێزتر گریت و زیانێن مەزن گەهینیتە دلێ تە.",blocks:[{heading:"هەمیشە ب دەستێن هشک",body:"بەری تو دەست بدەیە سویچەکێ کارەبایێ، دڤێت دەستێن تە ب تەمامی هشک بن و چو ئاڤ پێڤە نەبیت.",image:"media/images/water_elec_1.png"},{heading:"حەمام و ئامێرێن ئەلیکترۆنی",body:"چو جاران مۆبایل، ئایپاد یان هەر ئامێرەکێ ب کارەبایێ کار دکەت نەبە د حەمامێ دا، بتایبەتی دەمێ ب شەحنێ ڤە بیت، چونکی ئاڤ و هەلم دشێن کارەبایێ بگەهیننە تە.",image:"media/images/water_elec_2.png"},{heading:"ئاڤا ڕژای ل سەر وایەران",body:"ئەگەر تە دیت ئاڤ ڕژایە سەر وایەرەکێ کارەبایێ یان پلاکەکێ، نێزیک نەبە و ئێکسەر بێژە مەزنان دا کو کارەبایێ ببڕن.",image:"media/images/water_elec_3.png"}],examples:["سشوارێ (ئامێرێ هشککرنا پرچێ) ب تنێ بکار نەئینە، و چو جاران نەبە نێزیکی ئاڤێ.","ئەگەر ل مەلەڤانگەهێ یان ل نێزیکی حەوزێ بی، دەست نەدە چو گلۆپ یان ئامێرێن کارەبایێ.","ئەگەر عەرد تەڕ بوو، نێزیکی ئامێرێن کارەبایێ نەبە و بێژە مەزنەکی."],video:"media/videos/lesson07_water_elec.mp4",game:{instruction:"شێوازێ دروست بۆ دەستدانا سویچێ کارەبایێ کیشکە؟",items:[{text:"ب دەستێن تەڕ و ئاڤاوی",emoji:"💦",correct:!1},{text:"ب دەستێن پاقژ و هشک",emoji:"✋",correct:!0},{text:"ب دەستێن سابوونی",emoji:"🧼",correct:!1},{text:"ل ناڤ بانیۆیێ",emoji:"🛁",correct:!1}]},activity:{prompt:"تو نوکە ژ حەمامێ دەردکەڤی و دەستێن تە تەڕن، تە دڤێت گلۆپێ ژوورێ هەلکەی، دێ چ کەی؟",image:"media/images/activity_water_elec.png",options:[{text:"پێشی دەستێن خوە ب خاولییەکێ هشک دکەم، پاشان گلۆپێ هەلدکەم",correct:!0},{text:"هەر ب تەڕی دەست ددەمە سویچێ کارەبایێ",correct:!1},{text:"ب جلکێن خوە دەستێن خوە هشک دکەم و دەست ددەمێ",correct:!1},{text:"هاوار دکەم تا کەسەک دهێت و بۆ من هەلدکەت",correct:!1}]}},{id:8,icon:"Building",emoji:"🧗",accent:"#4f46e5",title:"مەترسییێن جهێن بلند",subtitle:"خوە ژ کەفتنێ بپارێزە",summary:"سەرکەفتن بۆ سەر مێز و دیوارێن بلند یاری نینە. جەستەیێ تە نازکە و کەفتن ژ جهەکێ بلند دشێت هەستییێن تە بشکێنیت و گەلەک تە بئێشینیت.",blocks:[{heading:"مێز و کورسی بۆ ڕوونشتنێ نە",body:"کورسی بۆ ڕوونشتنێ یە و مێز بۆ خوارنێ یە، نە بۆ هندێ کو تو ل سەر ڕاوەستی یان پێ بچیە سەر دۆلابان.",image:"media/images/heights_1.png"},{heading:"بالکۆن و پەنجەرە د مەترسیدارن",body:"چو جاران خوە ب سەر پەنجەرەیێ یان دیوارێ بالکۆنێ دا نەچەمینە، چونکی تو دشێی ب ساناهی هەڤسەنگییا خوە ژ دەست بدەی و بکەڤی.",image:"media/images/heights_2.png"},{heading:"ل سەر عەردی یارییێ بکە",body:"هەمیشە ل سەر عەردی یان ل ناڤ باخچێ یارییێ بکە، دا کو ئەگەر تو بکەڤی ژی، زیان نەگەهیتە تە.",image:"media/images/heights_3.png"}],examples:["ل سەر قەنەپە و نڤینان باز نەدە، چونکی تو دشێی ل سەر سەرێ خوە بکەڤی.","چو جاران بۆ دیتنا دەرڤە سەرنەکەڤە سەر کورسییێن نێزیکی پەنجەرەیێ.","ئەگەر تشتەکێ تە ل جهەکێ بلند بوو، هەول نەدە ب تنێ بگەهیێ، بێژە بابێ یان دایکێ."],video:"media/videos/lesson08_heights.mp4",game:{instruction:"کیش جهـ ژ ڤان سەلامەتە بۆ یارییێ؟",items:[{text:"ل سەر دیوارێ بالکۆنێ",emoji:"🧱",correct:!1},{text:"ل سەر مافوورێ ژوورێ",emoji:"🏃",correct:!0},{text:"ل سەر مێزا خوارنێ",emoji:"🪟",correct:!1},{text:"ل سەر چلێن داران",emoji:"🌳",correct:!1}]},activity:{prompt:"یارییا تە یا خۆشتڤی کەفتیە سەر دۆلابەکا بلند و دەستێ تە ناگەهیتێ، دێ چ کەی؟",image:"media/images/activity_heights.png",options:[{text:"دێ بێژمە کەسەکێ مەزن و ب ئارامی ل هیڤییێ بمینم تا بۆ من بینیتە خوارێ",correct:!0},{text:"دێ ب خوە سەرکەڤمە سەر دۆلابێ",correct:!1},{text:"دێ چەند کورسییان دانمە سەر ئێک دا بگەهمێ",correct:!1},{text:"دێ ب دارەکێ لێ دەم تا بکەڤیتە خوارێ و بشکێت",correct:!1}]}},{id:9,icon:"Candy",emoji:"🍬",accent:"#db2777",title:"مەترسییێن داقۆرتاندنێ",subtitle:"تشتێن بچووک و خەندقاندن",summary:"دەڤێ مە بۆ خوارن و ڤەخوارنێ یە. دڤێت ئەم گەلەک وریا بین و چو تشتێن دی نەکەینە دەڤێ خوە، چونکی هندەک تشت دشێن ڕێکا هەناسێ بگرن و مە بخەندقینن.",blocks:[{heading:"پارەیێن ئاسنی و مۆرک",body:"پارەیێن ئاسنی، مۆرک و پاترییێن بچووک یێن دەمژمێران نە بۆ خوارنێ نە. ئەگەر ئەڤ تشتە بچنە ناڤ گەرووی، گەلەک مەترسیدارن.",image:"media/images/swallow_1.png"},{heading:"دەرمان شەکرۆک نینە",body:"حەپکێن دەرمانی ڕەنگێن جوان هەنە و وەک شەکرۆکان دیار دبن، بەلێ ئەگەر تو ب خوە بخۆی، دێ ژەهراوی بی. تەنێ دەمێ دایک یان باب ددەنە تە، دەرمانی بخۆ.",image:"media/images/swallow_2.png"},{heading:"پاراستنا ڕێکا هەناسێ",body:"هەر تشتەکێ خوارن نەبیت و تو بکەیە دەڤێ خوە، دشێت د گەروویێ تە دا گیر ببیت و نەهێلیت تو هەناسێ وەرگری. هەمیشە تشتێن بچووک ژ دەڤێ خوە دویر بێخە.",image:"media/images/swallow_3.png"}],examples:["قەپاخێ قەلەمی نەکە دەڤێ خوە، چونکی دشێت ب ساناهی بچیتە د گەروویێ تە دا.","تۆڤکێن فێقییان (وەک قەیسی و زەیتوونان) نەداقۆرتینە، ئێکسەر ژ دەڤێ خوە دەربێخە.","ئەگەر تە تشتەک داقۆرتاند، ئێکسەر بێژە مەزنان، تەنانەت ئەگەر تو باش ژی بی."],video:"media/videos/lesson09_swallow.mp4",game:{instruction:"کیشک ژ ڤان تشتان بۆ خوارنێ دروستن؟",items:[{text:"سێڤ و فێقی",emoji:"🍎",correct:!0},{text:"پارەیێ ئاسنی",emoji:"🪙",correct:!1},{text:"مۆرکێن ڕەنگین",emoji:"📿",correct:!1},{text:"نان و سەموون",emoji:"🍞",correct:!0}]},activity:{prompt:"تە دیت خوشکا تە یا بچووک پاترییەکا بچووک یا یارییان کرە دەڤێ خوە، دێ چ کەی؟",image:"media/images/activity_swallow.png",options:[{text:"ئێکسەر ب دەنگێ بلند گازی دایکێ دکەم و دبێژمێ کا خوشکا من چ کرە دەڤێ خوە",correct:!0},{text:"دێ پێ کەنم و تەماشە کەم",correct:!1},{text:"ئەز ژی دێ ئێکێ کەمە دەڤێ خوە",correct:!1},{text:"دێ ل هیڤییێ بمینم تا خوشکا من بداقۆرتینیت",correct:!1}]}},{id:10,icon:"MapPin",emoji:"🗺️",accent:"#9333ea",title:"بەرزەبوون ل جهێن قەرەبالغ",subtitle:"ئەگەر تو ژ دایک و بابێ خوە جودا بووی",summary:"ئەگەر ل بازاڕی، ل مۆلێ یان ل سەیرانێ تو ژ مالباتا خوە جودا بووی و بەرزە بووی، نەترسە. تەنێ پێدڤییە تو بزانی دێ چ کەی، دا کو دایک و باب ب زووترین دەم تە ببیننەڤە.",blocks:[{heading:"ل جهێ خوە بوەستە",body:"ئەگەر تە دیت دایک و باب ل دۆر تە نینن، غار نەدە و ل وان نەگەڕە. ل جهێ خوە بوەستە، چونکی ئەو دێ ب زووترین دەم ل وی جهی ل تە گەڕێن و تە ببیننەڤە.",image:"media/images/lost_1.png"},{heading:"داخوازا هاریکارییێ بکە",body:"ئەگەر کەس نەهات، ل نێزیک خوە پۆلیسەکی، پاسەوانەکێ مۆلێ، کارمەندەکێ دوکانێ یان دایکەکا زارۆک دگەل ببینە و بێژێ: ئەز بەرزە بوویمە.",image:"media/images/lost_2.png"},{heading:"پێزانینێن تە یێن گرنگ",body:"هەول بدە ناڤێ خوە یێ سیانی و ژمارەیا تەلەفۆنا دایکێ یان بابێ ژبەر بکەی، دا کو ئەوێن هاریکارییا تە دکەن بشێن پەیوەندییێ ب وان بکەن.",image:"media/images/lost_3.png"}],examples:["چو جاران دەستێ دایکێ ل بازاڕی بەرنەدە.","چو جاران دگەل کەسێن نەناس نەچە چو جهان، تەنانەت ئەگەر شەکرۆکان ژی بدەنە تە.","ئارام ببە و نەگری، چونکی ترس ناهێلیت تو باش هزر بکەی.","ل جهێن ڕۆناهی و خەلک لێ بمینە و نەچە کۆلانێن تاری."],video:"media/videos/lesson10_lost.mp4",game:{instruction:"ئەگەر تو بەرزە بووی، کێ دشێت هاریکارییا تە بکەت؟",items:[{text:"پۆلیس یان پاسەوان",emoji:"👮‍♂️",correct:!0},{text:"کەسەکێ نەناس",emoji:"👤",correct:!1},{text:"دایکەکا زارۆک دگەل",emoji:"👩‍👧‍👦",correct:!0},{text:"زەلامەکێ ترسناک",emoji:"🦹‍♂️",correct:!1}]},activity:{prompt:"تو ل مۆلەکێ بەرزە بووی و دایک و بابێ خوە نابینی، دێ چ کەی؟",image:"media/images/activity_lost.png",options:[{text:"ل جهێ خوە دمینم و ناچمە چو جهان تا ئەو دهێن، یان دبێژمە کەسەکێ جهێ باوەرییێ",correct:!0},{text:"ب ڕەڤین بەرەڤ دەرگەهێ مۆلێ دچم و دچمە دەرڤە",correct:!1},{text:"دگەل کەسەکێ نەناس دچم چونکی دبێژیت دێ تە بەمە دەف وان",correct:!1},{text:"دچمە بن کورسییەکێ و خوە ڤەدشێرم",correct:!1}]}},{id:11,icon:"Baby",emoji:"🎡",accent:"#65a30d",title:"سەلامەتی ل باخچێ یارییان",subtitle:"یاریکرن ب ڕێز و بێ مەترسی",summary:"باخچێ یارییان جهەکێ گەلەک خۆشە بۆ یارییێ و ناسکرنا هەڤالێن نوو، بەلێ دا کو کەس بریندار نەبیت، دڤێت ئەم هندەک ڕێسایێن زێڕین پەیڕەو بکەین.",blocks:[{heading:"هەڤالێن خوە پال نەدە",body:"ل سەر جۆلانێ یان خلیسۆکێ، چو جاران هەڤالێن خوە پال نەدە، چونکی کەفتن ل سەر بەرد و عەردێ ڕەق دشێت برینێن دژوار چێ بکەت.",image:"media/images/playground_1.png"},{heading:"ڕێزبەندی و نۆرەگرتن",body:"فێر ببە کو ل هیڤییا نۆرا خوە بمینی. نۆرەگرتن نیشانا زیرەکییا تە و ڕێزگرتنا تە یە بۆ هەڤالێن تە.",image:"media/images/playground_2.png"},{heading:"سنوورێن باخچێ",body:"چو جاران ژ پەرژینێ باخچێ دەرنەکەڤە. ئەگەر تەپکا تە چوو دەرڤە، ب تنێ نەچە دویڤ دا، بێژە دایکێ یان مامۆستایێ.",image:"media/images/playground_3.png"}],examples:["خیزێ نەهاڤێژە هەوایێ، چونکی دچیتە د چاڤێن هەڤالێن تە دا.","ل پێشییا جۆلانێ دەمێ دلڤیت نەوەستە، دا کو ل تە نەدەت.","ئەگەر تە دیت یارییەک شکەستییە، یارییێ پێ نەکە و بێژە بەرپرسێ باخچێ."],video:"media/videos/lesson11_playground.mp4",game:{instruction:"کیشک ژ ڤان ڕەفتاران یێن پالەوانێ سەلامەتییێ نە؟",items:[{text:"پالدانا هەڤالان بۆ پێشکەفتنێ د نۆرێ دا",emoji:"✋",correct:!1},{text:"ڕاوەستان ب ئارامی د ڕێزێ دا",emoji:"⏱️",correct:!0},{text:"شەڕکرن ل سەر یارییان",emoji:"🥊",correct:!1},{text:"هاریکارییا هەڤالێن بچووکتر",emoji:"🤝",correct:!0}]},activity:{prompt:"هەڤالەکێ تە ل پێشییا تە یە و دڤێت بچیتە سەر یارییێ، دێ چ کەی؟",image:"media/images/activity_playground.png",options:[{text:"دێ ب ئارامی ل هیڤییێ بمینم تا نۆرا من دهێت",correct:!0},{text:"دێ وی پال دەم دا کو ئەز زووتر سەرکەڤم",correct:!1},{text:"دێ هاوار کەم و قێرینێ کەم",correct:!1},{text:"دێ چمە جهەکێ دی و پەرژینی بڕم",correct:!1}]}},{id:12,icon:"Dog",emoji:"🐕",accent:"#d97706",title:"ئاژەلێن کۆلانێ و نەناس",subtitle:"چەوانییا مامەلەکرنێ دگەل سە و پشیکان",summary:"ئەو ئاژەلێن ل کۆلانێ دگەڕێن و ئەم خودانێن وان ناناسین، دشێن مەترسیدار بن. هندەک ژ وان دترسن یان نەخۆشن و دشێن مرۆڤی بگەزن.",blocks:[{heading:"دەست نەدە ئاژەلێن نەناس",body:"تەنانەت ئەگەر پشیکەک یان سەیەک گەلەک جوان ژی بیت، دەست نەدێ. دبیت تە بگەزیت یان ب نینۆکان تە ڕەندینیت، و دشێن نەخۆشییان بگەهیننە تە.",image:"media/images/dogs_1.png"},{heading:"وەک دارەکێ ڕاوەستە",body:"ئەگەر سەیەک بەرەڤ تە هات: نەڕەڤە! وەک دارەکێ ب بێدەنگی ڕاوەستە، دەستێن خوە نێزیکی جەستەیێ خوە بگرە و تەماشەی چاڤێن سەی نەکە، تا ئەو دچیت.",image:"media/images/dogs_2.png"},{heading:"بێژە مەزنان",body:"ئەگەر تە ئاژەلەکێ بریندار یان تووڕە ل نێزیکی مالێ دیت، نێزیکی وی نەبە و ئێکسەر بێژە بابێ یان دایکێ. ئەگەر ئاژەلەکی تو گەستی یان ب نینۆکان بریندار کری، ئێکسەر بێژە مەزنەکی دا کو تە ببەنە دەف پزیشکی.",image:"media/images/dogs_3.png"}],examples:["چو جاران بەرد و تشتان نەهاڤێژە ئاژەلان، چونکی دێ تووڕە بن و هێرشێ کەنە سەر تە.","دەمێ ئاژەل خوارنێ دخۆن یان نڤستینە، نێزیکی وان نەبە.","کلک و گوهێن پشیکان نەکێشە، چونکی دێ تە ڕەندینن."],video:"media/videos/lesson12_dogs.mp4",game:{instruction:"ئەگەر سەیەکێ نەناس بەرەڤ تە هات، دێ چ کەی؟",items:[{text:"دێ ب لەز ڕەڤم",emoji:"🏃",correct:!1},{text:"دێ بەردان هاڤێژمێ",emoji:"🪨",correct:!1},{text:"دێ وەک دارەکێ ب بێدەنگی ڕاوەستم",emoji:"🧍",correct:!0},{text:"دێ هاوار کەم و دەستێن خوە هەژینم",emoji:"🗣️",correct:!1}]},activity:{prompt:"پشیکەکا بچووک ل سەر جاددەیێ دگریت، دێ چ کەی؟",image:"media/images/activity_dogs.png",options:[{text:"ژ دویر ڤە تەماشە دکەم و دبێژمە دایکێ دا کو هاریکارییا وێ بکەت",correct:!0},{text:"دچم و ئێکسەر هەمبێز دکەم",correct:!1},{text:"ب لنگێ خوە پال ددەمێ",correct:!1},{text:"دچمە دویڤ دا و دڕەڤینم",correct:!1}]}},{id:13,icon:"Wind",emoji:"👃",accent:"#475569",title:"ناسکرنا بێهنا غازێ و مەترسییێن وێ",subtitle:"بێهن ئاگەهدارییا مە دکەت",summary:"هندەک بێهن ل ناڤ مالێ وەک زەنگا ئاگەهدارکرنێ نە. بێهنا غازێ یان بێهنا سۆتنێ نیشان ددەن کو مەترسییەکا مەزن هەیە.",blocks:[{heading:"بێهنا هێکێن خرابووی (غاز)",body:"غاز ب خوە بێ بێهنە، بەلێ ب قەستی بێهنەکا خراب تێ دکەن دا کو ئەم بزانین ئەگەر غاز دەرکەفت. ئەگەر بێهنا غازێ هاتە تە، دەست نەدە چو سویچێن کارەبایێ.",image:"media/images/gas_1.png"},{heading:"پێشی دەرکەڤە",body:"ڕانەوەستە دا پەنجەرەیان ڤەکەی. ئێکسەر دەرکەڤە دەرڤە و بێژە مەزنەکی. زارۆک چ جاران دەستێ خوە نادەنە غازێ.",image:"media/images/gas_2.png"},{heading:"ژ ئاڤاهی دەرکەڤە",body:"ل وی جهێ بێهن لێ دهێت نەمینە. ئێکسەر دەرکەڤە دەرڤە و بێژە مەزنەکی. مەزن ژ دەرڤە پەیوەندییێ ب ١١٥ دکەن، نە ژ ناڤ مالێ.",image:"media/images/gas_3.png"}],examples:["چو جاران دەستکارییا وەلڤە و کلیلێن غازێ نەکە.","ل گەراجێن گرتی یێن ترمبێلان نەمینە، چونکی دوکێلا ترمبێلێ ژەهراوییە.","ئەگەر بێهنا سۆتنا وایەرێن کارەبایێ هاتە تە، ئێکسەر بێژە بابێ یان دایکێ."],video:"media/videos/lesson13_gas.mp4",game:{instruction:"ئەگەر بێهنا غازێ ل مەتبەخێ هاتە تە، دێ چ کەی؟",items:[{text:"دێ گلۆپێ هەلکەم دا ببینم چ چێبوویە",emoji:"💡",correct:!1},{text:"دێ بێژمە کەسەکێ مەزن",emoji:"🗣️",correct:!0},{text:"دێ شخاتەکێ هەلکەم",emoji:"🔥",correct:!1},{text:"دێ ژ مالێ دەرکەڤمە دەرڤە",emoji:"🚪",correct:!0}]},activity:{prompt:"تو ل مەتبەخێ یی و بێهنەکا توند یا غازێ دهێت، دێ چ کەی؟",image:"media/images/activity_gas.png",options:[{text:"ئێکسەر دەردکەڤمە دەرڤە و دبێژمە کەسەکێ مەزن",correct:!0},{text:"دچمە نێزیکی تەباخێ دا بزانم غاز ژ کیڤە دهێت",correct:!1},{text:"سویچێ پانکێ هەلدکەم دا بێهن بچیت",correct:!1},{text:"چو تشتەکی ناکەم و ل جهێ خوە دمینم",correct:!1}]}},{id:14,icon:"FlaskConical",emoji:"🧴",accent:"#0d9488",title:"دەفر و شلەمەنییێن نەناس",subtitle:"تام نەکە و ڤەنەخۆ",summary:"ل ناڤ مالێ گەلەک دەفر و بوتلێن ڕەنگاوڕەنگ هەنە کو ڕەنگێن وان وەک شەربەتێ د جوانن، بەلێ د ڕاستییێ دا ماددەیێن کیمیایی و ژەهری تێدانە کو بۆ پاقژکرنێ دهێنە بکارئینان.",blocks:[{heading:"ڤەنەخۆ و تام نەکە",body:"هەر شلەمەنییەکا تو نەناسی، چو جاران تام نەکە و ڤەنەخۆ. دبیت دەرمانێ پاقژکرنا حەمامێ یان عەردی بیت و زیانێ بگەهینیتە جەستەیێ تە.",image:"media/images/poison_1.png"},{heading:"هەمیشە پرسیار بکە",body:"بەری تو تشتەکێ نەناس بخۆی یان ڤەخۆی، ژ دایکێ یان بابێ بپرسە: ئەرێ ئەڤە دهێتە خوارن؟ ئەگەر وان دەستوور نەدا تە، دەست نەدێ.",image:"media/images/poison_2.png"},{heading:"ماددەیێن پاقژکرنێ د مەترسیدارن",body:"کلۆر و دەرمانێن دی یێن پاقژکرنێ تەنێ بۆ پاقژکرنا مالێ نە. هندەک ژ وان دشێن پێست و چاڤێن تە بسۆژن یان تە ژەهراوی بکەن.",image:"media/images/poison_3.png"}],examples:["دەرمانێن کێزک و مێش و مۆران ژەهرن، چو جاران بێهن نەکە.","بوتلێن دەرمانان یێن مالێ یاری نینن، دەست نەدێ.","ئەگەر تە تشتەکێ نەناس ڤەخوار، ئێکسەر بێژە دایکێ یان بابێ دا کو پەیوەندییێ ب ئەمبوولانسێ (١٢٢) بکەن."],video:"media/videos/lesson14_poison.mp4",game:{instruction:"کیشک ژ ڤان تشتان بۆ ڤەخوارنێ دروستن؟",items:[{text:"شەربەتا پرتەقالێ",emoji:"🧃",correct:!0},{text:"دەرمانێ پاقژکرنا عەردی",emoji:"🧴",correct:!1},{text:"شلەمەنییا کلۆری",emoji:"🧪",correct:!1},{text:"شیرێ سپی",emoji:"🥛",correct:!0}]},activity:{prompt:"تە بوتلەکا شین یا جوان ل بن دەستشۆکێ دیت و تو یێ تێهنی، دێ چ کەی؟",image:"media/images/activity_poison.png",options:[{text:"دەست نادەمێ و دچمە دەف دایکێ و پرسیارێ دکەم",correct:!0},{text:"کێمەکێ تام دکەم دا بزانم کا چییە",correct:!1},{text:"دڕێژمە سەر عەردی و یارییێ پێ دکەم",correct:!1},{text:"دکەمە د پەرداخەکی دا و ڤەدخۆم",correct:!1}]}},{id:15,icon:"CloudRain",emoji:"🌧️",accent:"#0284c7",title:"باران و مەترسییا لافاوان",subtitle:"خوە ژ ئاڤا لافاوێ بپارێزە",summary:"باران بۆ ڕوەک و عەردی گەلەک ب مفایە، بەلێ ئەگەر بارانەکا توند بباریت، دشێت ببیتە لافاو. ئاڤا لافاوێ گەلەک ب هێزە و دشێت ژیانا مە بێخیتە مەترسییێ.",blocks:[{heading:"ل ناڤ مالێ بمینە",body:"دەمێ بارانەکا ب هێز دباریت، باشترین و سەلامەتترین جهـ ناڤ مالێ یە. ل بن بارانا توند یارییێ نەکە.",image:"media/images/flood_1.png"},{heading:"نەچە ناڤ ئاڤا جاددەیێ",body:"ئاڤا لافاوێ پیسە و نەخۆشییان ب خوە ڤە دگریت. هەروەسا گەلەک ب هێزە، ئاڤەکا کێم ژی دشێت تە بخەتە عەردی و دگەل خوە ببەت.",image:"media/images/flood_2.png"},{heading:"ژ ڕووبار و جۆکان دویر بکەڤە",body:"ل دەمێ بارانێ، ئاستێ ئاڤا ڕووبار و جۆکان ب لەز بلند دبیت. هەمیشە ژ قەراخێن ئاڤێ دویر بکەڤە.",image:"media/images/flood_3.png"}],examples:["ئەگەر بارانەکا توند باری و ئاڤ ڕابوو، دگەل مەزنان ژ جهێن نزم بچنە جهێن بلند.","دەمێ بارانێ چەترێ بکار بینە دا کو جەستەیێ تە هشک بمینیت.","دەمێ بارانێ پێلاڤێن لاستیکی لبەر بکە، بەلێ چو جاران نەچە ناڤ ئاڤا لافاوێ."],video:"media/videos/lesson15_flood.mp4",game:{instruction:"دەمێ بارانەکا توند دباریت، کیش جهـ ژ هەمییان سەلامەتترە؟",items:[{text:"ناڤ باخچێ",emoji:"🏕️",correct:!1},{text:"ل ناڤ مالێ",emoji:"🏠",correct:!0},{text:"ناڤ ڕووباری",emoji:"🌊",correct:!1},{text:"ل سەر جاددەیێ",emoji:"🛣️",correct:!1}]},activity:{prompt:"تو دچیە دەرڤە و دبینی جاددە هەمی بوویە ئاڤ و لافاو، دێ چ کەی؟",image:"media/images/activity_flood.png",options:[{text:"ناچمە ناڤ ئاڤێ، دزڤڕمە ناڤ مالێ و دبێژمە مەزنان",correct:!0},{text:"دچمە ناڤ ئاڤا جاددەیێ و مەلەڤانییێ دکەم",correct:!1},{text:"تەنێ لنگێن خوە دکەمە تێدا و یارییێ دکەم",correct:!1},{text:"تەپکا خوە دهاڤێژمە ناڤ ئاڤێ دا کو ئاڤ ببەت",correct:!1}]}},{id:16,icon:"Bus",emoji:"🚌",accent:"#ca8a04",title:"ترمبێلێن مەزن و خالێن کۆر",subtitle:"خوە ژ ناڤچەیێن مەترسیدار دویر بێخە",summary:"لۆری، پاس و ترمبێلێن مەزن وەک ترمبێلێن بچووک نینن. شۆفێرێن وان هندەک جهێن ل دۆر ترمبێلێ نابینن، کو دبێژنێ خالێن کۆر (No-Zone). ئەگەر تو ل وێرێ بی، شۆفێر تە نابینیت و دبیت ترمبێل ل تە بدەت.",blocks:[{heading:"ناڤچەیا قەدەغە (No-Zone)",body:"ل پشت لۆرییێ، ل پێشییا وێ و ل هەردوو لایێن وێ خالێن کۆر هەنە. ئەگەر تو نەشێی چاڤێن شۆفێری د ئایینەیێ دا ببینی، ئەو ژی تە نابینیت. ژ لۆری و پاسان دویر بمینە.",image:"media/images/car_back_1.png"},{heading:"بن ترمبێلێ جهێ یارییێ نینە",body:"ئەگەر تەپک یان یارییا تە چوو بن ترمبێلەکێ (تەنانەت ئەگەر یا ڕاوەستیای ژی بیت)، ب چو شێوەیان نەچە بن ترمبێلێ. ئێکسەر گازی کەسەکێ مەزن بکە دا کو بۆ تە دەربێخیت.",image:"media/images/car_back_2.png"},{heading:"مەودایێ زڤڕینێ",body:"دەمێ لۆری و پاس دزڤڕن، جهەکێ مەزن پێدڤی دبن و گەلەک جاران دچنە سەر ڕێکا پیادەیان ژی. هەمیشە سێ هەنگاڤان ژ قەراخا جاددەیێ دویر بوەستە.",image:"media/images/car_back_3.png"}],examples:["چو جاران دەست یان سەرێ خوە ژ پەنجەرەیا پاسێ یان ترمبێلێ دەرنەئێخە.","گەراج جهێ یارییێ نینە، چونکی ترمبێل ل وێرێ ب پاشڤە دچن و شۆفێر تە نابینن.","هەمیشە ل هیڤییێ بمینە تا پاس ب تەمامی ڕادوەستیت، پاشان داکەڤە."],video:"media/videos/lesson16_car_back.mp4",game:{instruction:"کیش جهـ ل نێزیکی ترمبێلێن مەزن مەترسیدارە؟",items:[{text:"ئێکسەر ل پشت لۆرییێ",emoji:"🚘",correct:!0},{text:"ناڤ باخچێ",emoji:"🌳",correct:!1},{text:"ئێکسەر ل پێشییا لۆرییێ",emoji:"🚚",correct:!0},{text:"ل دویرییا ١٠ میتران",emoji:"🏠",correct:!1}]},activity:{prompt:"تەپکا تە ڕەڤی و چوو بن لۆرییەکا مەزن کو شۆفێر تێدایە، دێ چ کەی؟",image:"media/images/activity_car_back.png",options:[{text:"ناچمە بن لۆرییێ و دچمە دەف بابێ دا کو ئەو بۆ من دەربێخیت",correct:!0},{text:"ب لەز دچمە بن لۆرییێ، چونکی شۆفێر یێ نڤستییە",correct:!1},{text:"ب دارەکێ درێژ ل تەپکێ ددەم تا دەردکەڤیت",correct:!1},{text:"دگریم تا شۆفێر ب خوە تەپکێ ددەتە من",correct:!1}]}},{id:17,icon:"Car",emoji:"🎗️",accent:"#4f46e5",title:"قاییشا سەلامەتییێ و ئایرباگ",subtitle:"پاراستنا تە ل ناڤ ترمبێلێ",summary:"قاییشا سەلامەتییێ وەک هەمبێزەکا ب هێزە کو تە ل سەر کورسییێ دگریت. ئەگەر ترمبێل ژنشکەکێ ڤە ڕاوەستیا، ئەڤ قاییشە ناهێلیت جەستەیێ تە ب توندی بەر تشتان بکەڤیت.",blocks:[{heading:"هەمیشە قاییشێ ببەستە",body:"بەری ترمبێل بلڤیت، دڤێت تو ل سەر کورسیکا زارۆکان بی و قاییشا تە ب دروستی بهێتە بەستن. ئەڤە نیشانا زیرەکییا تە یە.",image:"media/images/seatbelt_1.png"},{heading:"جهێ زارۆکان ل پاشێ یە",body:"ئەو زارۆکێن ژ ١٣ سالان بچووکتر، دڤێت هەمیشە ل سەر کورسییێن پاشێ ڕوونن. ل پێشییێ ئایرباگ (کیسکا هەوایێ) هەیە و دەمێ ب لەز دپەقیت، دشێت زیانێ بگەهینیتە زارۆکان.",image:"media/images/seatbelt_2.png"},{heading:"تا ترمبێل نەوەستیت نەلڤە",body:"چو جاران قاییشێ ڤەنەکە و ژ جهێ خوە نەلڤە، تا ترمبێل ب تەمامی ڕادوەستیت و شۆفێر دەستووری ددەتە تە.",image:"media/images/seatbelt_3.png"}],examples:["چو جاران دەرگەهێ ترمبێلێ ڤەنەکە دەمێ ترمبێل ل ڕێ دچیت.","دەمێ ترمبێل ل ڕێ دچیت، ب دەنگێ بلند دگەل شۆفێری نەئاخڤە دا کو هزرا وی مژوول نەبیت.","ل کورسییا پاشێ یارییێن توند نەکە، دا کو شۆفێر مژوول نەبیت."],video:"media/videos/lesson17_seatbelt.mp4",game:{instruction:"کیش ڕەفتار د ناڤ ترمبێلێ دا دروستن؟",items:[{text:"بەستنا قاییشا سەلامەتییێ",emoji:"✅",correct:!0},{text:"دەرئێخستنا سەری ژ پەنجەرەیێ",emoji:"🤪",correct:!1},{text:"ڕوونشتن ل سەر کورسییا پاشێ",emoji:"💺",correct:!0},{text:"ڤەکرنا دەرگەهی دەمێ ترمبێل دچیت",emoji:"🚪",correct:!1}]},activity:{prompt:"تو سوارێ ترمبێلێ بووی و تە دڤێت ل سەر کورسییا پێشییێ ڕوونی، دێ چ کەی؟",image:"media/images/activity_seatbelt.png",options:[{text:"دچمە کورسییا پاشێ و قاییشێ دبەستم، چونکی بۆ زارۆکان سەلامەتترە",correct:!0},{text:"دگریم دا کو بابێ من ڕێکێ بدەت ل پێشییێ ڕوونم",correct:!1},{text:"قاییشێ نابەستم چونکی یا توندە",correct:!1},{text:"دەمێ ترمبێل دچیت، ئەز دێ دەرگەهی ڤەکەم",correct:!1}]}},{id:18,icon:"AlertTriangle",emoji:"☢️",accent:"#dc2626",title:"هێمایێن مەترسییێ ل هەمی جیهانێ",subtitle:"زمانێ وێنەیان بناسە",summary:"ل هەمی جیهانێ هندەک وێنە و هێمایێن تایبەت دهێنە بکارئینان دا کو بێ ئاخفتن مە ژ مەترسییێ ئاگەهدار بکەن. ناسکرنا ڤان هێمایان نیشانا زیرەکییا تە یە.",blocks:[{heading:"کەلەسەر و هەستی (ژەهر)",body:"ئەڤ هێمایە (☠️) نیشانا ماددەیێن ژەهراوی و کوژەکە. هەر تشتەکێ ئەڤ وێنە ل سەر بیت، ب چو شێوەیان دەست نەدێ و نێزیکی وی نەبە.",image:"media/images/danger_signs_1.png"},{heading:"هێمایا گڕا ئاگری (سۆتێنەر)",body:"ئەڤ وێنە نیشان ددەت کو ئەو ماددە ب لەز ئاگر دگریت. دڤێت ژ ئاگر و گەرمییێ دویر بیت، و تو ژی دەست نەدێ.",image:"media/images/danger_signs_2.png"},{heading:"بروسکا زەر (کارەبایا ب هێز)",body:"ئەڤ هێمایە نیشان ددەت کو ل ڤی جهی کارەبایەکا گەلەک ب هێز هەیە کو دشێت مرۆڤی بکوژیت. چو جاران نێزیکی وی جهی نەبە.",image:"media/images/danger_signs_3.png"}],examples:["نیشانا سۆر یا X دبێژیت: ئەڤ کارە قەدەغەیە.","هێمایا تیشکێ (☢️) ل هندەک جهێن نەخۆشخانان دهێتە دیتن، ژ وان جهان دویر بکەڤە.","هێمایێن خڕ یێن شین ڕێنماییێن سەلامەتییێ نە و دڤێت ئەم وان ب جهـ بینین."],video:"media/videos/lesson18_danger_signs.mp4",game:{instruction:"ئەڤ هێمایە (☠️) چ دبێژیتە مە؟",items:[{text:"ماددەیێن ژەهراوی و کوژەک",emoji:"🧪",correct:!0},{text:"ئاڤا پاقژ بۆ ڤەخوارنێ",emoji:"💧",correct:!1},{text:"خوارنا خۆش",emoji:"🍕",correct:!1},{text:"جهێ یارییێن زارۆکان",emoji:"🎮",correct:!1}]},activity:{prompt:"تە وێنێ کەلەسەری و هەستییان ل سەر دەرگەهێ کۆگەهەکێ دیت، دێ چ کەی؟",image:"media/images/activity_danger_signs.png",options:[{text:"ئێکسەر ژێ دویر دکەڤم، نێزیکی دەرگەهی نابم و دبێژمە مەزنەکی",correct:!0},{text:"دچمە ژوورێ دا بزانم چ ل وێرێ یە",correct:!1},{text:"ب بەردان ل دەرگەهی ددەم",correct:!1},{text:"یارییێ ل بەر دەرگەهی دکەم چونکی وێنەیەکێ سەرنجڕاکێشە",correct:!1}]}},{id:19,icon:"Award",emoji:"🏆",accent:"#ca8a04",title:"پالەوانێ سەلامەتییێ و بەرپرسیاری",subtitle:"تو نوکە شارەزا و سەرکەفتی",summary:"دەستخۆش! تو گەلەک ڕێسایێن سەلامەتییێ فێر بووی. نوکە تو نە تەنێ زارۆکەکی، بەلکو پالەوانەکێ سەلامەتییێ یی ل ناڤ جڤاکێ مە دا.",blocks:[{heading:"تو یێ هشیار و وریایی",body:"تو نوکە دزانی چەوا خوە ژ مەترسییێن ئاگری، کارەبایێ، لافاوێ و جاددەیێ بپارێزی. ئەڤە هێزا تە یا ڕاستەقینەیە.",image:"media/images/hero_1.png"},{heading:"هاریکارییا کەسێن دی بکە",body:"ئەرکێ تە وەک پالەوان ئەوە کو ئەوا تو فێر بووی بێژیە هەڤال، خوشک و برایێن خوە ژی، دا کو هەمی پاراستی بن.",image:"media/images/hero_2.png"},{heading:"پەیڕەوکرنا ڕێنماییێن سەلامەتییێ",body:"هەمیشە گوهدارییا دایک و بابێ خوە، مامۆستایان و تیمێن بەرگرییا شارستانی بکە. ڕێسایێن سەلامەتییێ بۆ پاراستنا ژیانا مە نە.",image:"media/images/hero_3.png"}],examples:["هەمیشە بەری هەر کارەکی هزر بکە: ئەرێ ئەڤە سەلامەتە؟","ئەگەر تە مەترسییەک دیت، بێ ترس بێژە مەزنان.","تو نموونەیا زیرەکییێ یی بۆ هەمی هەڤالێن خوە."],video:"media/videos/lesson19_hero.mp4",game:{instruction:"ڕەفتارێن دروست یێن پالەوانێ سەلامەتییێ کیشکن؟",items:[{text:"پاراستنا خوە و کەسێن دی",emoji:"🛡️",correct:!0},{text:"یاریکرن ب شخاتە و چەرخێ",emoji:"🔥",correct:!1},{text:"هاریکارییا مالباتێ و هەڤالان",emoji:"🤝",correct:!0},{text:"شەڕکرن دگەل هەڤالان",emoji:"👊",correct:!1}]},activity:{prompt:"تە دیت هەڤالەکێ تە ل باخچێ دڤێت یارییێ ب وایەرەکێ کارەبایێ یێ بڕی بکەت، دێ چ کەی؟",image:"media/images/activity_hero.png",options:[{text:"دێ بێژمێ: نێزیک نەبە! و ئێکسەر بێژمە مامۆستایێ یان دایکێ",correct:!0},{text:"ئەز ژی دێ دگەل وی یارییێ پێ کەم",correct:!1},{text:"دێ لێ دەم دا کو ڕاوەستیت",correct:!1},{text:"بێدەنگ دبم و چو نابێژم",correct:!1}]}},{id:20,icon:"Truck",emoji:"🚒",accent:"#dc2626",title:"پالەوانێن ئاگرکوژاندنێ",subtitle:"کارمەندێن ڕێڤەبەرییا بەرگرییا شارستانی",summary:"کارمەندێن بەرگرییا شارستانی ئەو پالەوانن یێن ڕاهێنانێن دژوار دیتین، دا کو ئاگری ڤەمرینن و ژیانا مرۆڤان و ئاژەلان د دەمێن تەنگاڤییێ دا ڕزگار بکەن.",blocks:[{heading:"ترمبێلا سۆر یا ئاگرکوژاندنێ",body:"ترمبێلا ئاگرکوژاندنێ یا سۆرە و ئاڤ، پەیژە و ئامێرێن ڕزگارکرنێ تێدانە. دەمێ تو دەنگێ زەنگا وێ (سایرەنێ) دبیستی، دڤێت ڕێک بۆ بهێتە ڤەکرن.",image:"media/images/firefighters_1.png"},{heading:"جلکێن پاراستنێ",body:"ئاگرکوژ جلکێن تایبەت لبەر دکەن کو ئاگر ناگرن و ناهێلن گەرمی بگەهیتە جەستەیێ وان. هەروەسا کلاو و پێلاڤێن وان گەلەک ب هێزن.",image:"media/images/firefighters_2.png"},{heading:"هاریکارێن جڤاکی",body:"ئاگرکوژ هەڤالێن مە نە. دەمێ مەترسییەک هەبیت، ئەو دهێن دا کو مە بپارێزن. ژ دەنگ، جلک و ماسکێن وان نەترسە و خوە ژ وان ڤەنەشێرە، چونکی ئەو بۆ ڕزگارکرنا تە دهێن.",image:"media/images/firefighters_3.png"}],examples:["دەمێ تو دەنگێ ترمبێلا ئاگرکوژاندنێ دبیستی، ژ جاددەیێ دویر بکەڤە و ل قەراخێ بوەستە.","ئاگرکوژ نە تەنێ ئاگری ڤەدمرینن، بەلکو خەلکێ گیربووی ژی ڕزگار دکەن.","ئەو کارەکێ پیرۆز دکەن بۆ پاراستنا خەلکێ باژێڕی."],video:"media/videos/lesson20_firefighters.mp4",game:{instruction:"کیشک ژ ڤان تشتان یێن ئاگرکوژانە؟",items:[{text:"ترمبێلا سۆر یا ئاگرکوژاندنێ",emoji:"🚒",correct:!0},{text:"پاسا گشتی",emoji:"🚌",correct:!1},{text:"کلاوێ ڕەق و جلکێن ئاگرکوژان",emoji:"🧑‍🚒",correct:!0},{text:"یارییا پشیکێ",emoji:"🐱",correct:!1}]},activity:{prompt:"تە دیت ترمبێلەکا سۆر یا ئاگرکوژاندنێ ب لەز و ب دەنگێ زەنگێ دهێت، دێ چ کەی؟",image:"media/images/activity_firefighters.png",options:[{text:"ژ جاددەیێ دویر دکەڤم و ل قەراخێ دڕاوەستم تا ترمبێل دەرباز دبیت",correct:!0},{text:"دچمە ناڤەڕاستا جاددەیێ دا کو وێنەیەکی بگرم",correct:!1},{text:"ب ڕەڤین بەرەڤ ترمبێلێ دچم",correct:!1},{text:"بەردان دهاڤێژمە ترمبێلێ",correct:!1}]}},{id:21,icon:"PhoneCall",emoji:"📞",accent:"#2563eb",title:"ژمارەیا هەوارهاتنێ ١١٥",subtitle:"پەیوەندی دگەل بەرگرییا شارستانی",summary:"١١٥ ژمارەیا بەرگرییا شارستانی یە. دەمێ ئاگر یان کارەساتەک چێ دبیت، ب ڤێ ژمارەیێ پەیوەندی دهێتە کرن و ئاگرکوژ ب لەز دهێن. هەر زارۆکەک دڤێت ڤێ ژمارەیێ ژبەر بکەت.",blocks:[{heading:"١١٥ بۆ تەنگاڤییێ یە",body:"ئەگەر تە ئاگرەک دیت، یان کەسەک ل بن داروبەردان ما، یان لافاو هات، ئێکسەر بێژە مەزنەکی دا کو پەیوەندییێ ب ١١٥ بکەت. ئەگەر چو مەزن ل دەف تە نەبوو، تو ب خوە ژ جهەکێ سەلامەت پەیوەندییێ ب ١١٥ بکە. بۆ برینداران و نەخۆشان، مەزن پەیوەندییێ ب ئەمبوولانسێ (١٢٢) دکەن.",image:"media/images/emergency_number_1.png"},{heading:"چەوانییا ئاخفتنا دروست",body:"دەمێ پەیوەندی دهێتە کرن، ب ئارامی باخڤە و بێژە: ناڤێ تە چییە، تو ل کیڤەیی و چ چێ بوویە.",image:"media/images/emergency_number_2.png"},{heading:"یاری ب ڤێ ژمارەیێ نابیت",body:"پەیوەندیکرن ب ١١٥ تەنێ بۆ تەنگاڤییێن ڕاستەقینەیە. یاری ب ڤێ ژمارەیێ قەدەغەیە، چونکی دبیت تیم دەرەنگ بگەهنە وان کەسێن پێدڤی ب هاریکارییێ.",image:"media/images/emergency_number_3.png"}],examples:["ژمارەیا ١١٥ ژبەر بکە: ئێک، ئێک، پێنج.","تەنێ دەمێ مەترسییەکا ڕاستەقینە هەبیت، پەیوەندی ب ١١٥ دهێتە کرن.","دەمێ تو دگەل ١١٥ دئاخڤی، تەلەفۆنێ دانەخە تا کارمەند نەبێژیتە تە."],video:"media/videos/lesson21_emergency_number.mp4",game:{instruction:"ژمارەیا فەرمی یا بەرگرییا شارستانی ل دهۆکێ چەندە؟",items:[{text:"١٢٣",emoji:"📱",correct:!1},{text:"١١٥",emoji:"🚒",correct:!0},{text:"٩٩٩",emoji:"📞",correct:!1},{text:"٤٤٤",emoji:"☎️",correct:!1}]},activity:{prompt:"تە ل کۆلانێ دیت دوکێل و بێهنەکا توند یا سۆتنێ ژ مالەکێ دهێت، دێ چ کەی؟",image:"media/images/activity_emergency_number.png",options:[{text:"ئێکسەر دبێژمە مەزنەکی دا کو پەیوەندییێ ب ١١٥ بکەت، ئەگەر کەس نەبوو، ئەز ب خوە پەیوەندییێ ب ١١٥ دکەم",correct:!0},{text:"ل جهێ خوە دمینم و دگریم",correct:!1},{text:"دچمە ناڤ وێ مالێ دا بزانم چ هەیە",correct:!1},{text:"خوە ڤەدشێرم دا کو پۆلیس من نەگرن",correct:!1}]}},{id:22,icon:"DoorOpen",emoji:"🚪",accent:"#16a34a",title:"پلانا دەرکەفتنا تەنگاڤییێ",subtitle:"ڕێکا دەرکەفتنا ب لەز و ب ئارامی",summary:"پلانا دەرکەفتنێ نەخشەیەکە کو نیشان ددەت ل دەمێ ئاگری یان مەترسییێ ئەم ژ کیش ڕێکێ دەرکەڤین و ل کیڤە کۆم ببین. دڤێت بۆ هەر مالەکێ و قوتابخانەیەکێ ئەڤ پلانە هەبیت، دا کو هەمی کەس ب ئارامی دەرکەڤن.",blocks:[{heading:"دوو ڕێکێن دەرکەفتنێ",body:"بۆ هەر ژوورەکێ دڤێت دوو ڕێکێن دەرکەفتنێ هەبن. ئەگەر ڕێکا ئێکێ هاتە گرتن، دگەل مەزنان ڕێکا دووێ بکار بینە.",image:"media/images/evacuation_1.png"},{heading:"خالا کۆمبوونێ",body:"پشتی تو ژ ئاڤاهی دەرکەفتی، بچە خالا کۆمبوونێ: جهەکێ ڤەکری و سەلامەت کو بەری نوکە هاتیە دیارکرن. ل وێرێ بمینە دا کو مەزن بزانن هەمی کەس دەرکەفتینە.",image:"media/images/evacuation_2.png"},{heading:"یاسایا زێڕین: نەزڤڕە ناڤدا",body:"دەمێ تو ژ ئاڤاهی دەرکەفتی، ب چو شێوەیان نەزڤڕە ناڤدا، نە بۆ یارییان و نە بۆ چو تشتێن دی. ژیانا تە ژ هەمی تشتان گرنگترە.",image:"media/images/evacuation_3.png"}],examples:["سالێ لایێ کێم دوو جاران، دگەل مالباتا خوە ڕاهێنانا دەرکەفتنێ بکە.","ل ئاڤاهییێن گشتی، بەرێ خوە بدە نیشانێن کەسک یێن دەرکەفتنێ (EXIT).","ئەگەر دوکێل هەبوو، ل سەر دەست و چۆکان بخشە، چونکی هەوایا پاقژتر ل نێزیکی عەردی یە."],video:"media/videos/lesson22_evacuation.mp4",game:{instruction:"ل دەمێ دەرکەفتنێ، کیشک ژ ڤان کاران دروستن؟",items:[{text:"زانینا ڕێکێن دەرکەفتنێ",emoji:"🚪",correct:!0},{text:"زڤڕین بۆ ناڤ ئاڤاهی بۆ ئینانا یارییان",emoji:"🧸",correct:!1},{text:"مان ل خالا کۆمبوونێ",emoji:"📍",correct:!0},{text:"مان ل ژوورێ تا تیم دهێن",emoji:"🛋️",correct:!1}]},activity:{prompt:"زەنگا ئاگری ل قوتابخانێ لێ دا و یارییێن تە د پۆلێ دا مان، دێ چ کەی؟",image:"media/images/activity_evacuation.png",options:[{text:"ب ئارامی و بێ پالدانا هەڤالان، دگەل مامۆستایێ ژ دەرگەهێ دەرکەفتنێ دچمە دەرڤە",correct:!0},{text:"دزڤڕمە پۆلێ دا یارییێن خوە بینم",correct:!1},{text:"دچمە بن مێزەکێ و خوە ڤەدشێرم",correct:!1},{text:"ب ڕەڤین و هاوار بەرەڤ ئەسانسۆرێ دچم",correct:!1}]}},{id:23,icon:"FireExtinguisher",emoji:"🧯",accent:"#ea580c",title:"ئامێر و کەرەستەیێن ئاگرکوژاندنێ",subtitle:"ئامێرێن ئاگرکوژان",summary:"تیمێن بەرگرییا شارستانی ئامێرێن گەلەک پێشکەفتی بکار دئینن بۆ ڤەمراندنا ئاگری و ڕزگارکرنا خەلکی. ئەڤ ئامێرە تەنێ بۆ مەزنان و ئاگرکوژانە، زارۆک دەست نادەنێ.",blocks:[{heading:"تەمرینک (ئامێرێ ئاگرکوژاندنێ)",body:"تەمرینک بوتلەکا ب فشارە، و ئاڤ، تۆز یان غازا CO₂ تێدایە. تەنێ مەزن بکار دئینن، زارۆک چو جاران دەست نادەنێ.",image:"media/images/fire_equipment_1.png"},{heading:"سۆندەیێن ئاڤێ یێن ب هێز",body:"ئاگرکوژ سۆندەیێن گەلەک ب هێز بکار دئینن کو ئاڤەکا گەلەک ب فشار دهاڤێژن و ئاگری ڤەدمرینن.",image:"media/images/fire_equipment_2.png"},{heading:"ئامێرێن بڕین و ڕزگارکرنێ",body:"ئەڤە ئامێرێن گەلەک ب هێزن کو ئاگرکوژ پێ ئاسنێ ترمبێلان دبڕن، دا کو خەلکێ گیربووی و برینداران ڕزگار بکەن.",image:"media/images/fire_equipment_3.png"}],examples:["چو جاران دەست نەدە تەمرینکێ، چونکی فشارەکا مەزن تێدایە.","بزانە تەمرینک ل مالێ و ل قوتابخانێ ل کیڤەیە، بەلێ دەست نەدێ.","ئەگەر ئاگرەکێ مەزن هەبوو، هەمی کەس ژ ئاڤاهی دەردکەڤن و تەنێ ئاگرکوژ ئامێرێن خوە بکار دئینن."],video:"media/videos/lesson23_fire_equipment.mp4",game:{instruction:"کیشک ژ ڤان ئامێران بۆ ڤەمراندنا ئاگری دهێنە بکارئینان؟",items:[{text:"تەمرینک",emoji:"🧯",correct:!0},{text:"تەپکا یارییێ",emoji:"⚽",correct:!1},{text:"سۆندەیێن ئاڤێ یێن ئاگرکوژان",emoji:"💦",correct:!0},{text:"پەرتووکێن خواندنێ",emoji:"📚",correct:!1}]},activity:{prompt:"ئاگرەکێ بچووک ل ناڤ سەتلا زبلی یا مەتبەخێ هەلبوو و بابێ تە ل مالێ یە، دێ چ کەی؟",image:"media/images/activity_fire_equipment.png",options:[{text:"ژ مەتبەخێ دەردکەڤم و ب دەنگێ بلند گازی بابێ خوە دکەم دا کو ئەو ئاگری ڤەمرینیت",correct:!0},{text:"ئەز دێ تەمرینکێ ڕاکەم و یارییێ پێ کەم",correct:!1},{text:"ب خوە ئاڤێ دڕێژمە سەر ئاگری",correct:!1},{text:"دچمە ژوورەکا دی و خوە ڤەدشێرم",correct:!1}]}},{id:24,icon:"CloudFog",emoji:"💨",accent:"#475569",title:"مەترسییا دوکێلێ و هەناسەدانا پاقژ",subtitle:"چەوانییا دەرکەفتنا سەلامەت ژ ناڤ دوکێلێ",summary:"دوکێلا ئاگری گەلەک جاران ژ ئاگری ب خوە مەترسیدارترە، چونکی ژەهراوییە و ناهێلیت مرۆڤ ب ساناهی هەناسێ بدەت. دوکێل و گەرمی بلند دبن، ژبەر هندێ هەوایا پاقژتر ل نێزیکی عەردی یە. خوە نزم بکە و دەرکەڤە: ئەڤە دێ ژیانا تە ڕزگار کەت.",blocks:[{heading:"خوە نزم بکە و بخشە",body:"گەرمی و دوکێل هەمیشە بلند دبن، ژبەر هندێ هەوایا پاقژتر ل نێزیکی عەردی دمینیت. ل سەر دەست و چۆکان بخشە و سەرێ خوە نزم بگرە تا تو دگەهیە دەرڤە. چو جاران د ناڤ دوکێلێ دا ب پێڤە ڕاوەستیای نەچە.",image:"media/images/smoke_1.png"},{heading:"پاراستنا دەڤ و لووتی",body:"ئەگەر پارچە قوماشەک ل دەف تە هەبوو، دەڤ و لووتێ خوە پێ بگرە. بەلێ بۆ گەڕیانا ل قوماشی ڕانەوەستە، چونکی قوماش ڕێکێ ل هەمی دوکێلێ ناگریت. ئێکسەر خوە نزم بکە و دەرکەڤە.",image:"media/images/smoke_2.png"},{heading:"بەری ڤەکرنێ دەرگەهی تاقی بکە",body:"بەری تو دەرگەهی ڤەکەی، ب پشتا دەستێ خوە دەست بدە دەرگەهی و دەسکێ وی. ئەگەر گەرم بوو، یان دوکێل ژ بن دەرگەهی دهات، ڤەنەکە و ڕێکەکا دی بکار بینە.",image:"media/images/smoke_check_door.png"},{heading:"دەرگەهی ل پشت خوە بگرە",body:"دەمێ تو ژ ژوورەکێ دەردکەڤی، دەرگەهی ل پشت خوە بگرە. دەرگەهێ گرتی ناهێلیت ئاگر و دوکێل ب لەز بچنە جهێن دی.",image:"media/images/smoke_3.png"},{heading:"پەنجەرەیان بێ هەوجە ڤەنەکە",body:"هەوا ئاگری مەزنتر دکەت، ژبەر هندێ پەنجەرە و دەرگەهان بێ هەوجە ڤەنەکە. ئەگەر تو د ژوورەکێ دا گیر بووی، دەرگەهی گرتی بهێلە، بچە بەر پەنجەرەیێ، دەستێ خوە بلڤینە و هاوار بکە دا کو ئاگرکوژ تە ببینن. چو جاران خوە ژ پەنجەرەیێ نەهاڤێژە.",image:"media/images/smoke_no_window.png"}],reference:[{heading:"ڕێسایێن سەرەکی",points:["✅ خوە نزم بکە و ل سەر دەست و چۆکان بخشە.","✅ ڕێکێن دەرکەفتنێ یێن مالا خوە بزانە.","✅ بەری ڤەکرنێ دەرگەهی ب پشتا دەستی تاقی بکە، ئەگەر گەرم بوو ڤەنەکە.","✅ دەرگەهی ل پشت خوە بگرە.","❌ خوە ل بن تەختی یان د دۆلابێ دا ڤەنەشێرە، و نەزڤڕە ناڤدا."]},{heading:"پشتی دەرکەفتنێ",points:["🌿 بچە خالا کۆمبوونێ و ل دەرڤە بمینە.","📞 بێژە مەزنەکی. مەزن ژ دەرڤە پەیوەندییێ ب ١١٥ دکەن، و ب ١٢٢ ژی ئەگەر کەسەک بریندار بوو.","⚠️ ئەگەر سەرێ تە دئێشیت، سەرێ تە دگەڕیت یان هەناسە ب زەحمەت دهێت، ئێکسەر بێژە مەزنەکی دا کو پەیوەندییێ ب ئەمبوولانسێ (١٢٢) بکەت."]}],examples:["دەمێ تو دوکێلێ دبینی، هاوار بکە: ئاگر! پاشان خوە نزم بکە و بەرەڤ ڕێکا دەرکەفتنێ بخشە.","ئەگەر تاری بوو، ل سەر دەست و چۆکان بمینە، دەستێ خوە ب دیواری ڤە بگرە و نزم بەرەڤ دەرگەهێ دەرکەفتنێ بخشە.","ئەگەر دەرگەه گەرم بوو، ڤەنەکە و ڕێکەکا دی بکار بینە.","ئەگەر تو نەشیای دەرکەڤی: دەرگەهی بگرە، خاولییەکێ بکە بن دەرگەهی، ل بەر پەنجەرەیێ دەستێ خوە بلڤینە و هاوار بکە. ئەگەر تەلەفۆن ل دەف تە هەبوو، پەیوەندییێ ب ١١٥ بکە و بێژە تو ل کیڤەیی."],video:"media/videos/lesson24_smoke.mp4",game:{instruction:"ئەگەر دوکێلا ڕەش د ژوورێ دا هەبوو، دێ چ کەی؟ (هەمی بەرسڤێن دروست هەلبژێرە)",items:[{text:"ب پێڤە ڕادوەستم و دمینم",emoji:"🧍",correct:!1},{text:"خوە نزم دکەم و ل سەر دەست و چۆکان دخشم",emoji:"🧎",correct:!0},{text:"پەنجەرەیان ڤەدکەم دا کو هەوا بهێت",emoji:"🪟",correct:!1},{text:"ئەگەر قوماشەک ل دەف من هەبیت، دەڤ و لووتێ خوە پێ دگرم",emoji:"🧣",correct:!0},{text:"بەری ڤەکرنێ، ب پشتا دەستی دەرگەهی تاقی دکەم",emoji:"🖐️",correct:!0},{text:"دەرگەهی ل پشت خوە دگرم",emoji:"🚪",correct:!0}]},activity:{prompt:"تو د ژوورا نڤستنێ دا یی و دوکێلا ڕەش ژ بن دەرگەهی دهێتە ژوور. دەرگەه گەلەک گەرمە. دێ چ کەی؟",image:"media/images/activity_smoke.png",options:[{text:"دەرگەهی ڤەناکەم، خوە نزم دکەم، دچمە بەر پەنجەرەیێ، دەستێ خوە دلڤینم و هاوار دکەم دا کو مەزن و ئاگرکوژ من ببینن",correct:!0},{text:"دەرگەهی ڤەدکەم و ب پێڤە دڕەڤمە دەرڤە",correct:!1},{text:"هەمی پەنجەرە و دەرگەهان ڤەدکەم دا کو ئاگر کێم ببیت",correct:!1},{text:"ل بن تەختی خوە ڤەدشێرم",correct:!1}]}},{id:25,icon:"Siren",emoji:"🚒",accent:"#dc2626",title:"ئاگرکوژێن قارەمان",subtitle:"ئەو کینە یێن د ترمبێلا سۆر دا؟",summary:"دەمێ ئاگرەک هەلدبیت یان ڕووداوەک چێ دبیت، قارەمانێن بەرگرییا شارستانی ب ترمبێلا سۆر دهێن! ئەو ژیانا خەلکی دپارێزن. ژمارەیا وان ١١٥ یە، و هەر زارۆکەک دڤێت ڤێ ژمارەیێ بزانیت.",blocks:[{heading:"ترمبێلا سۆر",body:"ترمبێلا ئاگرکوژان مەزن و سۆرە و سایرەنا وێ هەیە. ئاڤ، سۆندە، پەیژە و ئامێرێن ڕزگارکرنێ تێدانە. دەمێ تو دبینی، ژ جاددەیێ دویر بکەڤە و ڕێکێ بۆ بهێلە.",image:"media/images/cd_truck.png"},{heading:"سایرەنا قارەمانان",body:'دەنگێ سایرەنێ "ووو-ووو-ووو" دبێژیت: "ئەم دهێین، ڕێکێ ڤەکەن!" ژێ نەترسە، ئەو بۆ هاریکارییا مە دهێن.',image:"media/images/cd_siren.png"},{heading:"١١٥ ژمارەیەکا گرنگە",body:"ئەگەر تە ئاگرەک یان ڕووداوەک دیت، ئێکسەر بێژە مەزنەکی دا کو پەیوەندییێ ب ١١٥ بکەت. ئەگەر تو ب تنێ بووی، ل سەر تەلەفۆنێ ١-١-٥ لێ بدە و ناڤێ خوە و جهێ خوە بێژە.",image:"media/images/cd_phone.png"}],examples:["ئاگرکوژ جلک و کلاوێن تایبەت لبەر دکەن دا کو ئاگر وان نەسۆژیت.","دەمێ ترمبێلا سۆر دهێت، دڤێت ترمبێلا مە بچیتە قەراخێ و ڕێکێ بۆ بهێلیت.","پەیوەندیکرن ب ١١٥ یاری نینە، تەنێ بۆ تەنگاڤییێن ڕاستەقینەیە."],video:"media/videos/lesson25_heroes.mp4",game:{instruction:"قارەمانێن بەرگرییا شارستانی کیش کاران دکەن؟",items:[{text:"ئاگری ڤەدمرینن",emoji:"🔥",correct:!0},{text:"پیتزایێ دفرۆشن",emoji:"🍕",correct:!1},{text:"خەلکێ گیربووی ڕزگار دکەن",emoji:"🆘",correct:!0},{text:"یارییا تەپا پێ دکەن",emoji:"⚽",correct:!1},{text:"ب پەیژەیان سەردکەڤن دا کو خەلکی ڕزگار بکەن",emoji:"🪜",correct:!0}]},activity:{prompt:"تو ل بەر پەنجەرەیێ یی و تە ترمبێلا سۆر ل سەر جاددەیێ دیت و دەنگێ سایرەنێ بیست. دێ چ کەی؟",image:"media/images/activity_truck.png",options:[{text:"ل جهێ خوە دمینم و دبێژمە دایک یان بابێ خوە: ترمبێلا ئاگرکوژان هات!",correct:!0},{text:"دڕەڤمە سەر جاددەیێ دا کو تەماشە بکەم",correct:!1},{text:"سۆلا خوە دهاڤێژمە ترمبێلێ",correct:!1},{text:"دترسم و خوە ژ ئاگرکوژان ڤەدشێرم",correct:!1}]}},{id:26,icon:"FireExtinguisher",emoji:"🧯",accent:"#dc2626",title:"بوتلا سۆر یا ئاگرکوژاندنێ",subtitle:"تەمرینک چییە؟",summary:"ل مالێ، قوتابخانێ و فەرمانگەهان بوتلەکا سۆر و گرنگ هەیە، ناڤێ وێ تەمرینکە. مەزن پێ ئاگرێن بچووک ڤەدمرینن. تو بکار نائینی، بەلێ باشە بزانی چییە و ل کیڤەیە.",blocks:[{heading:"تەنێ بۆ مەزنانە",body:"تەمرینک گرانە و فشارەکا ب هێز تێدایە. زارۆک چو جاران تەمرینکێ بکار نائینن. ئەگەر ئاگرەک هەلبوو، ژ وێرێ دەرکەڤە و ب دەنگێ بلند گازی مەزنەکی بکە.",image:"media/images/ext_adult.png"},{heading:"جۆرێن جودا، بکارئینانا جودا",body:"تەمرینک جۆرێن جودا هەن. ژ ڕەنگی ب تەنێ نەزانە بۆ کیش ئاگرێ یە؛ پەیڤ و نیشانێن ل سەرێ وێ بکارئینانا وێ دیار دکەن. مەزنەکێ فێرکری جۆرێ گونجای هەلدبژێریت. تو دوور بکەڤە و مەزنەکی ئاگەهدار بکە.",image:"media/images/ext_colors.png"},{heading:"تەمرینکا مالا تە ل کیڤەیە؟",body:'ژ دایک و بابێ خوە بپرسە: "تەمرینکا مالا مە ل کیڤەیە؟" گەلەک جاران ل نێزیکی دەرگەهێ مەتبەخێ یان ل کۆریدۆرێ یە. بزانە ل کیڤەیە، بەلێ دەست نەدێ.',image:"media/images/ext_location.png"}],examples:["تەمرینک گرانە و تو نەشێی هەلگری، ئەو بۆ مەزنانە.","ئەگەر ئاگر ل پلاکەکێ یان ئامێرەکێ کارەبایێ هەبوو، ئاڤێ نەڕێژە سەر! کارەبا دێ تە گریت. ئێکسەر بێژە مەزنەکی.","مەزن هەر هەیڤەکێ تەمرینکێ دپشکنن و سالێ جارەکێ دبەنە دەف پسپۆری، دا کو هەردەم ئامادە بیت."],video:"media/videos/lesson26_extinguisher.mp4",game:{instruction:"دەمێ تو ئاگرەکێ بچووک دبینی، دێ چ کەی؟",items:[{text:"هاوار دکەم: ئاگر! و ب لەز دەردکەڤم",emoji:"🏃",correct:!0},{text:"هەول ددەم تەمرینکێ بکار بینم",emoji:"🧯",correct:!1},{text:"مەزنەکی ئاگەهدار دکەم",emoji:"👨",correct:!0},{text:"ب خوە ئاڤێ دڕێژمە سەر ئاگری",emoji:"💧",correct:!1}]},activity:{prompt:'تو بوتلا سۆر ل کۆریدۆرێ دبینی. هەڤالێ تە دبێژیت: "وەرە دا یارییێ پێ بکەین!" دێ چ کەی؟',image:"media/images/activity_ext.png",options:[{text:"دبێژمێ: نە! ئەڤە یاری نینە، ئەڤە بۆ ئاگری یە. پاشان دبێژمە مەزنەکی",correct:!0},{text:"دێ پێکڤە یارییێ پێ کەین",correct:!1},{text:"دێ مێخا سەلامەتییێ کێشم",correct:!1},{text:"دێ پال دەمێ تا بکەڤیتە عەردی",correct:!1}]}},{id:27,icon:"HeartHandshake",emoji:"❤️‍🩹",accent:"#db2777",title:"هاریکارییا هەڤالێ بریندار",subtitle:"ئەگەر هەڤالەکێ تە کەفت، دێ چ کەی؟",summary:"دەمێ هەڤالەکێ تە دکەڤیت یان بریندار دبیت، تو دشێی هاریکارییا وی بکەی. تو پزیشک نینی، بەلێ تو دشێی ئارام بمینی و ب لەز بێژیە مەزنەکی. مەزن دزانن دێ چ کەن، و ئەگەر پێدڤی بوو، پەیوەندییێ ب ئەمبوولانسێ (١٢٢) دکەن.",blocks:[{heading:"ئێکەم: ئارام بمینە",body:'گری هاریکارییێ ناکەت. ل نێزیکی هەڤالێ خوە بمینە و بپرسە: "تو باشی؟" پاشان بێژێ: "نەترسە، ئەز دێ گازی مەزنەکی کەم."',image:"media/images/help_calm.png"},{heading:"دووەم: گازی مەزنەکی بکە",body:'ب لەز و ب دەنگێ بلند گازی بکە: "مامۆستا!" یان "دایێ!" ئەگەر چو مەزن ل نێزیک نەبوو، ب لەز بچە و مەزنەکی بینە. مەزن دێ پەیوەندییێ ب ئەمبوولانسێ (١٢٢) کەت ئەگەر پێدڤی بوو.',image:"media/images/help_call.png"},{heading:"سێیەم: هاریکارییا بچووک",body:`تا مەزن دهێت، تو دشێی ڤان کاران بکەی:

• 🩸 خوین: پارچە قوماشەکێ پاقژ بدە هەڤالێ خوە دا کو ب خوە ب هێز ل سەر برینێ بگریت.
• 🦴 ئەگەر دەست یان لنگ گەلەک دئێشیت: هەڤالێ خوە نەلڤینە.
• 🔥 سۆتن: بێژە مەزنەکی، ئەو دێ جهێ سۆتی ٢٠ خولەکان ل بن ئاڤا فێنک ڕاگریت. سەهۆل و مەعجوونا ددانان بۆ سۆتنێ باش نینن.`,image:"media/images/help_basic.png"}],examples:["ئەگەر سەر یان ستۆیێ هەڤالێ تە دئێشیت، وی نەلڤینە و نەهێلە ڕاببیت، ل هیڤییا مەزنەکی بمینن.","دەست نەدە خوینا کەسێن دی، و پشتی هاریکارییێ دەستێن خوە ب ئاڤ و سابوونێ بشۆ.","ئەگەر تو ترسیای، گازی مەزنەکی بکە. داخوازکرنا هاریکارییێ نیشانا زیرەکییێ یە."],video:"media/videos/lesson27_first_aid.mp4",game:{instruction:"کیشک ژ ڤان کاران بۆ هەڤالێ بریندار دروستن؟",items:[{text:"ئارام دمینم و گازی مەزنان دکەم",emoji:"🧘",correct:!0},{text:"دگریم و دڕەڤم",emoji:"😭",correct:!1},{text:"پارچە قوماشەکێ پاقژ ددەمێ دا کو ل سەر برینێ بگریت",emoji:"🩹",correct:!0},{text:"پێ دکەنم و یارییێ دکەم",emoji:"🤡",correct:!1},{text:"دبێژمە مەزنەکی دا کو پەیوەندییێ ب ئەمبوولانسێ (١٢٢) بکەت",emoji:"📞",correct:!0}]},activity:{prompt:'هەڤالێ تە ل قوتابخانێ ژ پلەکانان کەفت و دبێژیت: "لنگێ من دئێشیت!" دێ چ کەی؟',image:"media/images/activity_help.png",options:[{text:"دبێژمێ: ئارام ببە! پاشان گازی مامۆستایێ دکەم و هەڤالێ خوە نالڤینم.",correct:!0},{text:"هەول ددەم وی هەلگرم و ببەمە مەتبەخێ",correct:!1},{text:"لنگێ وی دکێشم دا بزانم کا شکەستییە یان نە",correct:!1},{text:"دچمە مال و چو نابێژم",correct:!1}]}}],t={lessons:e};export{t as default,e as lessons};
